func goldenBytes(t *testing.T, name string) []byte {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", name))
	if err != nil {
		t.Fatalf("read golden %s (generate with testdiff/goldens/dump_linktracker.py): %v",
			name, err)
	}
	return data
}

func decodeGolden(t *testing.T, name string, into any) {
	t.Helper()
	dec := json.NewDecoder(bytes.NewReader(goldenBytes(t, name)))
	dec.UseNumber()
	if err := dec.Decode(into); err != nil {
		t.Fatalf("decode golden %s: %v", name, err)
	}
}

func pyNumber(v any) any {
	switch x := v.(type) {
	case json.Number:
		if i, err := x.Int64(); err == nil {
			return i
		}
		if f, err := x.Float64(); err == nil {
			return f
		}
		return x.String()
	case []any:
		out := make([]any, len(x))
		for i, e := range x {
			out[i] = pyNumber(e)
		}
		return out
	default:
		return v
	}
}

// writeNote writes a vault note whose frontmatter source is the URL
// (the VaultIndex dedupe key) — the reconfix _note helper.
func writeNote(t *testing.T, vault, rel, url string) string {
	t.Helper()
	return writeNoteBody(t, vault, rel,
		"---\nsource: "+url+"\ntitle: t\n---\n"+strings.Repeat("x", 300)+"\n")
}

func writeNoteBody(t *testing.T, vault, rel, body string) string {
	t.Helper()
	path := filepath.Join(vault, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(path), 0o777); err != nil {
		t.Fatalf("mkdir %s: %v", path, err)
	}
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatalf("write %s: %v", path, err)
	}
	return path
}

// ---------------------------------------------------------------------------
// test_onespelling.py: TestTheVaultIndexKeys
// ---------------------------------------------------------------------------

func TestVaultIndexOneNoteAnswersBothSpellings(t *testing.T) {
	vault := t.TempDir()
	// The note carries the same frontmatter keys build_website_note
	// produces (the index reads source:/managed_by:/fetch_status:
	// only — the pipeline's builder is Phase-4 territory).
	writeNoteBody(t, vault, "Design/Assets/Cleanup Pictures.md",
		"---\nsource: https://cleanup.pictures\n"+
			"aliases: []\ntags: []\ncategory: Design\n"+
			"subcategory: Assets & Resources\nfetch_status: full\n"+
			"managed_by: gitcurator\n---\nbody\n")
	idx := NewVaultIndex(vault, links.NormalizeWebsiteURL)
	idx.Rebuild(nil)
	if !idx.HasURL("https://cleanup.pictures/") {
		t.Fatal("has_url(with slash) = false")
	}
	if !idx.HasURL("https://cleanup.pictures") {
		t.Fatal("has_url(without slash) = false")
	}
	want := filepath.Join(vault, "Design", "Assets",
		"Cleanup Pictures.md")
	if got := idx.GetPath("https://cleanup.pictures/"); got != want {
		t.Fatalf("get_path = %q; want %q", got, want)
	}
	if idx.Count() != 1 { // one note, not two
		t.Fatalf("count = %d; want 1", idx.Count())
	}
}

// ---------------------------------------------------------------------------
// test_lawfix.py: TestTrashSkipLists.test_vault_index_skips_trash
// ---------------------------------------------------------------------------

func TestVaultIndexSkipsTrash(t *testing.T) {
	vault := filepath.Join(t.TempDir(), "v")
	writeNote(t, vault, "Design/Real.md", "https://example.com/")
	writeNote(t, vault, ".trash/banned-domains/x_com_1.md",
		"https://x.com/1")
	idx := NewVaultIndex(vault, links.NormalizeWebsiteURL)
	idx.Rebuild(nil)
	if idx.Count() != 1 {
		t.Fatalf("count = %d; want 1 (.trash skipped)", idx.Count())
	}
	if idx.HasURL("https://x.com/1") {
		t.Fatal("a .trash note counted as in-vault")
	}
}

// ---------------------------------------------------------------------------
// test_intakefix.py: TestMissingRepoNote.test_vault_index_dedupes_
//                     through_the_note
// ---------------------------------------------------------------------------

func TestVaultIndexDedupesThroughTheMissingRepoNote(t *testing.T) {
	vault := filepath.Join(t.TempDir(), "gh")
	folder := filepath.Join(vault, "_missing")
	if err := os.MkdirAll(folder, 0o777); err != nil {
		t.Fatal(err)
	}
	note := notebuilder.BuildMissingRepoNote(
		"https://github.com/THUDM/CogVideoX", "THUDM", "CogVideoX", 1)
	path := filepath.Join(folder, "THUDM_CogVideoX_missing.md")
	if err := os.WriteFile(path, []byte(note), 0o644); err != nil {
		t.Fatal(err)
	}
	idx := NewVaultIndex(vault, nil)
	idx.Rebuild(nil)
	if !idx.HasURL("https://github.com/THUDM/CogVideoX") {
		t.Fatal("the missing-repo note is not a dedupe key")
	}
	if !idx.HasURL("https://github.com/THUDM/CogVideoX/") {
		t.Fatal("the trailing-slash spelling does not fold")
	}
	if idx.HasURL("https://github.com/THUDM/Other") {
		t.Fatal("a different repo folded in")
	}
	// ...and deleting the note is the re-check trigger:
	if err := os.Remove(path); err != nil {
		t.Fatal(err)
	}
	idx2 := NewVaultIndex(vault, nil)
	idx2.Rebuild(nil)
	if idx2.HasURL("https://github.com/THUDM/CogVideoX") {
		t.Fatal("the deleted note still indexes")
	}
}

// The TestInboxTableRouting leg: the websites VaultIndex does NOT see
// _inbox rows (skipped).
func TestVaultIndexSkipsInbox(t *testing.T) {
	vault := t.TempDir()
	writeNote(t, vault, "_inbox/x_twitter_links.md",
		"https://x.com/i/status/1")
	idx := NewVaultIndex(vault, nil)
	idx.Rebuild(nil)
	if idx.Count() != 0 {
		t.Fatalf("count = %d; want 0 (_inbox skipped)", idx.Count())
	}
}

// ---------------------------------------------------------------------------
// The generated pure corpus — manifest bytes + SafeMocName.
// ---------------------------------------------------------------------------

type ltPure struct {
	Schema        int     `json:"schema"`
	ManifestBytes string  `json:"manifest_bytes"`
	SafeMocName   [][]any `json:"safe_moc_name"`
}

func TestLinktrackerPureGolden(t *testing.T) {
	var g ltPure
	decodeGolden(t, "linktracker_pure.golden.json", &g)

	// The manifest bytes — the Go writer's byte-parity pin.
	fixed := &Manifest{
		BatchID:    "20260101_000000",
		CreatedAt:  "2026-01-01T00:00:00",
		Source:     "bot",
		TotalLinks: 4,
		Links: []*ManifestLink{
			{URL: "https://github.com/o/one",
				Normalized: "https://github.com/o/one", Type: "github",
				Status: "processed", NotePath: strPtr("/vault/AI/one.md"),
				ProcessedAt: strPtr("2026-01-01T00:00:01")},
			{URL: "https://github.com/o/two/",
				Normalized: "https://github.com/o/two", Type: "github",
				Status: "failed",
				Error:  strPtr("HTTP 404 — 🗑️ not found")},
			{URL: "https://example.com/x",
				Normalized: "https://example.com/x", Type: "non-github",
				Status:      "recorded",
				NotePath:    strPtr("_inbox/non_github_links.md"),
				ProcessedAt: strPtr("2026-01-01T00:00:02")},
			{URL: "https://example.com/walled",
				Normalized: "https://example.com/walled",
				Type:       "non-github", Status: "blocked",
				Error: strPtr("self domain")},
		},
	}
	// The JSON round-trip: the Go reader must parse the reference's
	// bytes back into the same shape (nil ⇔ null).
	parsed := &Manifest{}
	if err := json.Unmarshal([]byte(g.ManifestBytes), parsed); err != nil {
		t.Fatalf("unmarshal the reference's manifest bytes: %v", err)
	}
	if len(parsed.Links) != len(fixed.Links) {
		t.Fatalf("parsed links = %d; want %d", len(parsed.Links),
			len(fixed.Links))
	}
	for i, want := range fixed.Links {
		got := parsed.Links[i]
		if got.URL != want.URL || got.Normalized != want.Normalized ||
			got.Type != want.Type || got.Status != want.Status {
			t.Errorf("parsed link %d = %+v; want %+v", i, got, want)
		}
		if (got.NotePath == nil) != (want.NotePath == nil) ||
			(got.NotePath != nil && *got.NotePath != *want.NotePath) {
			t.Errorf("parsed link %d note_path mismatch", i)
		}
		if (got.Error == nil) != (want.Error == nil) ||
			(got.Error != nil && *got.Error != *want.Error) {
			t.Errorf("parsed link %d error mismatch: %v vs %v", i,
				got.Error, want.Error)
		}
		if (got.ProcessedAt == nil) != (want.ProcessedAt == nil) ||
			(got.ProcessedAt != nil &&
				*got.ProcessedAt != *want.ProcessedAt) {
			t.Errorf("parsed link %d processed_at mismatch", i)
		}
	}
	// The writer: byte-identical to the reference's json.dump bytes.
	if got := pyDumpManifest(fixed); got != g.ManifestBytes {
		t.Errorf("pyDumpManifest != the reference's bytes:\n got: %q\nwant: %q",
			got, g.ManifestBytes)
	}

	// The SafeMocName battery.
	for _, tc := range g.SafeMocName {
		if len(tc) != 2 {
			t.Fatalf("moc case = %v", tc)
		}
		in, _ := tc[0].(string)
		want, _ := tc[1].(string)
		if got := SafeMocName(in); got != want {
			t.Errorf("SafeMocName(%q) = %q; golden %q", in, got, want)
		}
	}
}

// ---------------------------------------------------------------------------
// The obsidian golden — the env-steered discovery battery.
// ---------------------------------------------------------------------------

func TestLinktrackerObsidianGolden(t *testing.T) {
	var g struct {
		Schema int      `json:"schema"`
		Found  []string `json:"found_vaults"`
	}
	decodeGolden(t, "linktracker_obsidian.golden.json", &g)

	fake := t.TempDir()
	appdata := filepath.Join(fake, "appdata")
	if err := os.MkdirAll(filepath.Join(appdata, "obsidian"), 0o777); err != nil {
		t.Fatal(err)
	}
	registry := map[string]any{
		"vaults": map[string]any{
			"id1": map[string]any{"path": filepath.Join(fake, "RegVault")},
			"id2": map[string]any{"path": filepath.Join(fake, "RegVault")},  // same path twice
			"id3": map[string]any{"path": filepath.Join(fake, "GoneVault")}, // not on disk
		},
	}
	data, _ := json.Marshal(registry)
	if err := os.WriteFile(
		filepath.Join(appdata, "obsidian", "obsidian.json"), data,
		0o644); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Join(fake, "RegVault"), 0o777); err != nil {
		t.Fatal(err)
	}
	home := filepath.Join(fake, "home")
	if err := os.MkdirAll(
		filepath.Join(home, "Documents", "MyVault", ".obsidian"),
		0o777); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(
		filepath.Join(home, "Documents", "NotAVault"), 0o777); err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(
		filepath.Join(home, "Obsidian", ".obsidian"), 0o777); err != nil {
		t.Fatal(err)
	}

	t.Setenv("APPDATA", appdata)
	t.Setenv("HOME", home)

	found := FindObsidianVaults()
	var rels []string
	for _, p := range found {
		rel, err := filepath.Rel(fake, p)
		if err != nil {
			rel = p
		}
		rels = append(rels, rel)
	}
	if !reflect.DeepEqual(rels, g.Found) {
		t.Errorf("found vaults = %v; golden %v", rels, g.Found)
	}
}

// ---------------------------------------------------------------------------
// The behavior golden — the VaultIndex battery over the crafted vaults.
// ---------------------------------------------------------------------------

func TestLinktrackerBehaviorGolden(t *testing.T) {
	var g struct {
		Schema int `json:"schema"`
		Probes struct {
			GhVault struct {
				Count          int             `json:"count"`
				Has            map[string]bool `json:"has"`
				PathQuotedBase string          `json:"path_quoted_basename"`
				LogLine        string          `json:"log_line"`
			} `json:"gh_vault"`
			WebVault struct {
				Count            int                `json:"count"`
				Has              map[string]bool    `json:"has"`
				SiteNotes        map[string]*string `json:"site_notes"`
				ConsolidatedBase string             `json:"consolidated_path_is_site_note"`
			} `json:"web_vault"`
			AddURL struct {
				HasNew      bool   `json:"has_new"`
				SiteNoteNew string `json:"site_note_new"`
				CountAfter  int    `json:"count_after"`
			} `json:"add_url"`
		} `json:"probes"`
	}
	decodeGolden(t, "linktracker_behavior.golden.json", &g)

	scratch := t.TempDir()

	// -- the GitHub-normalizer vault --
	v1 := filepath.Join(scratch, "ghvault")
	writeNoteBody(t, v1, "AI/Real.md",
		"---\nsource: \"https://github.com/o/quoted\"\ntitle: t\n---\n"+
			strings.Repeat("x", 300)+"\n")
	writeNoteBody(t, v1, "_review/Reviewed.md",
		"---\nsource: https://github.com/o/reviewed\n---\nreviewed note\n")
	writeNoteBody(t, v1, "_moc/Index.md",
		"---\nsource: https://github.com/o/moc\n---\nmoc\n")
	writeNoteBody(t, v1, "_inbox/table.md",
		"---\nsource: https://github.com/o/inbox\n---\ninbox\n")
	writeNoteBody(t, v1, "attachments/pic.md",
		"---\nsource: https://github.com/o/attach\n---\nattach\n")
	writeNoteBody(t, v1, ".obsidian/config.md",
		"---\nsource: https://github.com/o/obsidian\n---\ncfg\n")
	writeNoteBody(t, v1, ".trash/banned-domains/x.md",
		"---\nsource: https://github.com/o/trashed\n---\nbanned\n")
	// an undecodable note: raw bytes (the strict read skips it)
	if err := os.WriteFile(
		filepath.Join(v1, "AI", "Undecodable.md"),
		[]byte("---\nsource: https://github.com/o/undecodable\n---\n"+
			"\xff\xfe invalid \xff\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	var logLines []string
	idx := NewVaultIndex(v1, nil)
	idx.Rebuild(func(msg, level string) { logLines = append(logLines, msg) })
	if idx.Count() != g.Probes.GhVault.Count {
		t.Errorf("gh count = %d; golden %d", idx.Count(),
			g.Probes.GhVault.Count)
	}
	for u, want := range g.Probes.GhVault.Has {
		if got := idx.HasURL(u); got != want {
			t.Errorf("gh has(%s) = %v; golden %v", u, got, want)
		}
	}
	if got := filepath.Base(idx.GetPath(
		"https://github.com/o/quoted")); got != g.Probes.GhVault.PathQuotedBase {
		t.Errorf("quoted path base = %q; golden %q", got,
			g.Probes.GhVault.PathQuotedBase)
	}
	if len(logLines) == 0 || logLines[0] != g.Probes.GhVault.LogLine {
		t.Errorf("log line = %v; golden %q", logLines,
			g.Probes.GhVault.LogLine)
	}

	// -- the websites-normalizer vault --
	v2 := filepath.Join(scratch, "webvault")
	writeNoteBody(t, v2, "Design/Assets/site.md",
		"---\nsource: https://cleanup.pictures\naliases: []\n"+
			"site_links: [https://cleanup.pictures/features, "+
			"\"https://cleanup.pictures/pricing\"]\n"+
			"category: Design\nmanaged_by: gitcurator\n"+
			"fetch_status: full\n---\nbody\n")
	writeNoteBody(t, v2, "Design/failed-site.md",
		"---\nsource: https://failed.example\n"+
			"managed_by: GitCurator\nfetch_status: failed\n---\n"+
			"placeholder\n")
	writeNoteBody(t, v2, "_review/review-site.md",
		"---\nsource: https://reviewed.example\n"+
			"managed_by: gitcurator\nfetch_status: full\n---\n"+
			"in review\n")
	writeNoteBody(t, v2, "Design/hand-site.md",
		"---\nsource: https://hand.example\nfetch_status: full\n---\n"+
			"no managed_by line\n")
	writeNoteBody(t, v2, "Design/boundary.md",
		"---\n"+strings.Repeat("#", 3850)+"\n"+
			"site_links: [https://boundary.example/within]\n---\n"+
			strings.Repeat("y", 300)+
			"\nsource: https://invisible.example\n")
	idx2 := NewVaultIndex(v2, links.NormalizeWebsiteURL)
	idx2.Rebuild(nil)
	if idx2.Count() != g.Probes.WebVault.Count {
		t.Errorf("web count = %d; golden %d", idx2.Count(),
			g.Probes.WebVault.Count)
	}
	for u, want := range g.Probes.WebVault.Has {
		if got := idx2.HasURL(u); got != want {
			t.Errorf("web has(%s) = %v; golden %v", u, got, want)
		}
	}
	for u, want := range g.Probes.WebVault.SiteNotes {
		got := idx2.SiteNoteFor(u)
		if want == nil {
			if got != "" {
				t.Errorf("site_note_for(%s) = %q; golden null", u, got)
			}
			continue
		}
		if got == "" || filepath.Base(got) != *want {
			t.Errorf("site_note_for(%s) = %q; golden %q", u, got, *want)
		}
	}
	if got := filepath.Base(idx2.GetPath(
		"https://cleanup.pictures/features")); got !=
		g.Probes.WebVault.ConsolidatedBase {
		t.Errorf("consolidated path base = %q; golden %q", got,
			g.Probes.WebVault.ConsolidatedBase)
	}

	// -- add_url learns the site map incrementally --
	pNew := writeNoteBody(t, v2, "Design/new-site.md",
		"---\nsource: https://newsite.example\n"+
			"managed_by: gitcurator\nfetch_status: full\n---\nnew\n")
	idx2.AddURL("https://newsite.example", pNew)
	if got := idx2.HasURL("https://newsite.example"); got !=
		g.Probes.AddURL.HasNew {
		t.Errorf("add_url has_new = %v; golden %v", got,
			g.Probes.AddURL.HasNew)
	}
	if got := filepath.Base(idx2.SiteNoteFor(
		"https://newsite.example")); got != g.Probes.AddURL.SiteNoteNew {
		t.Errorf("add_url site note = %q; golden %q", got,
			g.Probes.AddURL.SiteNoteNew)
	}
	if idx2.Count() != g.Probes.AddURL.CountAfter {
		t.Errorf("add_url count = %d; golden %d", idx2.Count(),
			g.Probes.AddURL.CountAfter)
	}
}
